selector_to_html = {"a[href=\"#term-source-extraction\"]": "<dt id=\"term-source-extraction\">source-extraction</dt><dd><p>Umbrella term for all of the individual processes that produce a segmented image.</p></dd>", "a[href=\"#term-functional-segmentation\"]": "<dt id=\"term-functional-segmentation\">functional segmentation</dt><dd><p>ROI detection based on pixelwise correlations across time, identifying spatially contiguous regions with similar activity patterns.</p></dd>", "a[href=\"#term-segmentation\"]": "<dt id=\"term-segmentation\">segmentation</dt><dd><p>The general process of dividing an image based on the contents of that image, in our case, based on neuron location.</p></dd>", "a[href=\"#term-roi_stats\"]": "<dt id=\"term-roi_stats\">roi_stats</dt><dd><p>Dictionary containing per-ROI statistics computed during detection, including area, compactness, skewness, and spatial coordinates.</p></dd>", "a[href=\"#glossary\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Glossary<a class=\"headerlink\" href=\"#glossary\" title=\"Link to this heading\">#</a></h1>", "a[href=\"#term-mean_img\"]": "<dt id=\"term-mean_img\">mean_img</dt><dd><p>The average of the registered movie over time. Used as a baseline representation of the structural signal.</p></dd>", "a[href=\"#term-max_proj\"]": "<dt id=\"term-max_proj\">max_proj</dt><dd><p>The maximum value per pixel over time. Highlights regions with high fluorescence, useful for detecting active areas.</p></dd>", "a[href=\"#term-npix_norm\"]": "<dt id=\"term-npix_norm\">npix_norm</dt><dd><p>Normalized pixel count of an ROI. The raw pixel count divided by expected size based on the <code class=\"docutils literal notranslate\"><span class=\"pre\">diameter</span></code> parameter. Helps the classifier reject ROIs that are abnormally small (noise) or large (merged cells, blood vessels).</p></dd>", "a[href=\"#term-pixel-resolution\"]": "<dt id=\"term-pixel-resolution\">pixel-resolution</dt><dd><p>The length of each pixel, in micron (px/um).</p></dd>", "a[href=\"#term-meanImgE\"]": "<dt id=\"term-meanImgE\">meanImgE</dt><dd><p>Enhanced mean image computed during registration (spatial high-pass of <code class=\"docutils literal notranslate\"><span class=\"pre\">mean_img</span></code>). Shown in the GUI as \u201cE: mean img (enhanced)\u201d; not a cellpose detection input.</p></dd>", "a[href=\"#term-deconvolution\"]": "<dt id=\"term-deconvolution\">deconvolution</dt><dd><p>The process performed after segmentation to the resulting traces to infer spike times from flourescence values.</p></dd>", "a[href=\"#term-compact\"]": "<dt id=\"term-compact\">compact</dt><dd><p>Spatial compactness of an ROI, measuring how circular/concentrated the pixels are. Computed as <code class=\"docutils literal notranslate\"><span class=\"pre\">(4</span> <span class=\"pre\">*</span> <span class=\"pre\">pi</span> <span class=\"pre\">*</span> <span class=\"pre\">area)</span> <span class=\"pre\">/</span> <span class=\"pre\">perimeter^2</span></code>. A perfect circle has compactness of 1.0; elongated or fragmented shapes have lower values. Used by the classifier because real neurons tend to be compact while artifacts are often irregular.</p></dd>", "a[href=\"#term-Delta-F-over-F0\"]": "<dt id=\"term-Delta-F-over-F0\">Delta F over F0</dt><dd><p><span class=\"math notranslate nohighlight\">\\(\\Delta F / F_0\\)</span> (Delta F over F naught) refers to the fractional change in fluorescence relative to a baseline signal F\u2080.\nThis is a common normalization used in calcium imaging and neural activity recordings.</p></dd>", "a[href=\"#term-Rigid-registration\"]": "<dt id=\"term-Rigid-registration\">Rigid-registration</dt><dd><p>The object retains shape and size.</p></dd>", "a[href=\"#term-Non-rigid-registration\"]": "<dt id=\"term-Non-rigid-registration\">Non-rigid-registration</dt><dd><p>The object is moved and transforms shape or size.</p></dd>", "a[href=\"#term-logistic-regression\"]": "<dt id=\"term-logistic-regression\">logistic regression</dt><dd><p>A statistical model that predicts binary outcomes (cell vs non-cell) by fitting a sigmoid function to input features. Suite2p\u2019s classifier uses logistic regression on ROI morphological features. The model outputs a probability between 0-1, thresholded at 0.5 by default to make the cell/non-cell decision. Training involves fitting the sigmoid curve to labeled examples so that cells map to high probabilities and non-cells map to low probabilities.</p></dd>", "a[href=\"#term-skewness\"]": "<dt id=\"term-skewness\">skewness</dt><dd><p>How often do you get an outlier in the pixel activity across time, good for calcium indicators because theyre flat relative to a few events over the course of a recording.</p></dd>", "a[href=\"#term-anatomical-segmentation\"]": "<dt id=\"term-anatomical-segmentation\">anatomical segmentation</dt><dd><p>ROI detection based solely on static images (e.g. mean or max projection), ignoring fluorescence time dynamics.</p></dd>", "a[href=\"#term-seed\"]": "<dt id=\"term-seed\">seed</dt><dd><p>A pixel or region in the image used as the <strong>starting point</strong> for growing a potential ROI.\nSeeding is based on high-intensity regions in the filtered image, and forms the initial guess\nfor the shape and location of a neuron.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
